-- Evita futuros expedientes duplicados entre registros activos.
CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_numero_expediente_unico
  ON projects(numero_expediente) WHERE numero_expediente <> '' AND deleted_at IS NULL;
